    "qty_out" INTEGER NOT NULL DEFAULT 0,
    "qty_available" INTEGER NOT NULL DEFAULT 0,
    "qty_inspect" INTEGER NOT NULL DEFAULT 0,
    "qty_defect" INTEGER NOT NULL DEFAULT 0,
    "qty_locked" INTEGER NOT NULL DEFAULT 0,
    "stock_status" INTEGER NOT NULL DEFAULT 1,
    "warehouse_id" BIGINT,
    "produce_date" DATE,
    "expire_date" DATE,
    "order_id" BIGINT,
    "in_time" TIMESTAMP,
