CREATE TABLE "wms_inventory" (
    "inventory_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "warehouse_id" BIGINT NOT NULL,
    "material_id" BIGINT NOT NULL,
    "batch_no" VARCHAR(80) NOT NULL DEFAULT '',
    "quantity" DECIMAL(18,4) NOT NULL DEFAULT 0,
    "locked_qty" DECIMAL(18,4) NOT NULL DEFAULT 0,
    "available_qty" DECIMAL(18,4) NOT NULL DEFAULT 0,
    "unit" VARCHAR(20) DEFAULT '',
    "status" INTEGER NOT NULL DEFAULT 1,
    "create_by" VARCHAR(64) DEFAULT '',
    "create_time" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "update_by" VARCHAR(64) DEFAULT '',
    "update_time" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("inventory_id"),
    CONSTRAINT "wms_inventory_uk_wh_mat_batch" UNIQUE ("warehouse_id", "material_id", "batch_no"),
    CHECK (quantity >= 0 AND locked_qty >= 0 AND quantity >= locked_qty),
    CHECK (available_qty = quantity - locked_qty)
);

