-- Fields used by the current model, missing from historical patches.
ALTER TABLE sal_ar_receivable_line ADD COLUMN produced_date DATE;
ALTER TABLE sal_ar_receivable_line ADD COLUMN remark VARCHAR(500);
ALTER TABLE scm_purchase_return ADD COLUMN has_replenishment INTEGER NOT NULL DEFAULT 0;
