-- Project table was previously created manually, outside the historical DDL.
CREATE TABLE pm_project (
    project_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_code VARCHAR(64) NOT NULL UNIQUE,
    project_name VARCHAR(200) NOT NULL,
    customer_name VARCHAR(200),
    product_name VARCHAR(200),
    manager VARCHAR(100),
    category_id BIGINT,
    priority VARCHAR(1) DEFAULT 'M',
    status INTEGER NOT NULL DEFAULT 0,
    start_date DATE,
    end_date DATE,
    actual_end_date DATE,
    budget NUMERIC(18,2),
    description TEXT,
    remark VARCHAR(500),
    create_by VARCHAR(64),
    create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_by VARCHAR(64),
    update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX pm_project_category_idx ON pm_project(category_id, status);
